"use client";

import React, { useState } from "react";
import { motion, useReducedMotion } from "motion/react";
import { ShieldAlert } from "lucide-react";
import { cn } from "@/lib/utils";

export interface DontPressButtonProps
  extends Omit<React.HTMLAttributes<HTMLButtonElement>, "onDrag" | "onDragStart" | "onDragEnd" | "onAnimationStart"> {
  className?: string;
}

export function DontPressButton({
  className,
  ...props
}: DontPressButtonProps) {
  const reduceMotion = useReducedMotion();
  const [warnings, setWarnings] = useState(0);
  const [isShaking, setIsShaking] = useState(false);

  const handleClick = () => {
    setWarnings((prev) => prev + 1);
    setIsShaking(true);
    setTimeout(() => setIsShaking(false), 400);
  };

  const warningTexts = [
    "DO NOT PRESS",
    "Seriously, don't!",
    "Stop it!",
    "Warning #3 triggered!",
    "System Alert! 🚨",
    "Self Destruct! 💣",
  ];

  return (
    <motion.button
      type="button"
      onClick={handleClick}
      animate={
        isShaking && !reduceMotion
          ? { x: [-6, 6, -6, 6, 0], y: [-2, 2, -2, 2, 0] }
          : {}
      }
      transition={{ duration: 0.3 }}
      className={cn(
        "flex items-center justify-center gap-2 rounded-2xl px-6 py-3 text-sm font-bold shadow-lg transition-colors select-none cursor-pointer border",
        warnings === 0
          ? "bg-red-600 text-white border-red-500 hover:bg-red-500"
          : warnings < 4
          ? "bg-amber-600 text-white border-amber-500"
          : "bg-purple-700 text-white border-purple-500 animate-pulse",
        className
      )}
      {...props}
    >
      <ShieldAlert className="h-4 w-4" />
      <span>{warningTexts[Math.min(warnings, warningTexts.length - 1)]}</span>
    </motion.button>
  );
}

export default DontPressButton;
